def solve(inp):
    H=len(inp); W=len(inp[0])
    seen=[[False]*W for _ in range(H)]; shapes=[]
    for r in range(H):
        for c in range(W):
            if inp[r][c] and inp[r][c]!=2 and not seen[r][c]:
                col=inp[r][c]; stack=[(r,c)]; comp=[]; seen[r][c]=True
                while stack:
                    y,x=stack.pop(); comp.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and inp[ny][nx]==col:
                            seen[ny][nx]=True; stack.append((ny,nx))
                shapes.append(comp)
    bar_row = 0 if any(v==2 for v in inp[0]) else H-1
    up = (bar_row==0)
    shapes.sort(key=lambda s: (min if up else max)(y for y,x in s), reverse=not up)
    out=[[0]*W for _ in range(H)]
    for c in range(W): out[bar_row][c]=2
    occupied={(bar_row,c) for c in range(W)}
    for s in shapes:
        colr=inp[s[0][0]][s[0][1]]; d=0
        if up:
            while all(y-d-1>=0 and (y-d-1,x) not in occupied for y,x in s): d+=1
        else:
            while all(y+d+1<H and (y+d+1,x) not in occupied for y,x in s): d+=1
        for y,x in s:
            out[y-d if up else y+d][x]=colr; occupied.add((y-d if up else y+d, x))
    return out
